// sample skewed. Buffers have no pitch ambiguity; stride comes from the Image
// plane (the same value the correct CPU path uses). Each uint holds 2 LE pixels.
layout(binding = 0) readonly buffer Bayer { uint codes[]; };""",
"""// Unspektra-style sampled-image view of the sensor plane: the HAL buffer is
// imported as a VK_FORMAT_R16_UINT VkImage (OPTIMAL tiling, SAMPLED usage)
// and fetched texel-exact. No pitch/tiling ambiguity reaches the shader;
// buffers that cannot expose R16_UINT sampled are rejected natively and the
// caller falls back to the lock+memcpy upload tier.
layout(binding = 0) uniform usampler2D rawImg;""")
s=s.replace("""uint fetchCode(ivec2 s) {
    uint idx = uint(s.y) * uint(p.u_pitch) + uint(s.x);
    uint word = codes[idx >> 1u];
    return ((idx & 1u) == 0u) ? (word & 0xFFFFu) : (word >> 16u);
}""",
"""uint fetchCode(ivec2 s) {
    return texelFetch(rawImg, s, 0).r;
}""")
p.write_text(s)
print("ok")
