        g->computeArmed = false;
        if (retired == VK_ERROR_DEVICE_LOST) return VFVK_DEVICE_LOST;
        return vr == VK_ERROR_DEVICE_LOST ? VFVK_DEVICE_LOST : VFVK_SUBMIT_FAILED;
    }
    g->computeArmed = false;
    return VFVK_OK;
